//! argparse's `--help`, byte for byte (T42 follow-up, t1220): a port of
//! `argparse.HelpFormatter` (usage building and wrapping, section layout, the
//! `max_help_position` rule) and of the `textwrap` pieces it uses, driven by the generated
//! table. Verified against `tests/cli_help.json`, recorded from the Python parser at
//! COLUMNS=80 with colour off; the fixture is regenerated by `tools/gen_cli_rs.py`.
//!
//! LIMIT: pinned to the argparse that recorded the fixture (Python 3.14: "options:",
//! usage wrapping rules); a different Python's wording is a fixture diff, not a bug here.

use crate::spec::{Arg, Cmd, Kind, Nargs};

const INDENT_INCREMENT: usize = 2;
const MAX_HELP_POSITION: usize = 24;

fn len(text: &str) -> usize {
    text.chars().count()
}

// ---- textwrap ---------------------------------------------------------------------------

fn is_letter(c: char) -> bool {
    // `[^\d\W]`: a word character that is not a digit (underscore counts).
    c.is_alphabetic() || c == '_'
}

fn is_wp(c: char) -> bool {
    // `[\w!"'&.,?]`
    c.is_alphanumeric() || c == '_' || "!\"'&.,?".contains(c)
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// `TextWrapper.wordsep_re` applied to one run of non-space characters.
fn split_word(tok: &[char]) -> Vec<String> {
    let n = tok.len();
    let mut out = Vec::new();
    let mut start = 0;
    while start < n {
        // "em-dash between words": dashes that follow a word-punctuation char and precede \w.
        if start > 0 && is_wp(tok[start - 1]) && tok[start] == '-' {
            let mut end = start;
            while end < n && tok[end] == '-' {
                end += 1;
            }
            if end - start >= 2 && end < n && is_word(tok[end]) {
                out.push(tok[start..end].iter().collect());
                start = end;
                continue;
            }
        }
        // "word": lazily extend until a break condition holds.
        let mut p = start + 1;
        loop {
            if p < n && tok[p] == '-' {
                let behind = (p >= 2 && is_letter(tok[p - 2]) && is_letter(tok[p - 1]))
                    || (p >= 3
                        && is_letter(tok[p - 3])
                        && tok[p - 2] == '-'
                        && is_letter(tok[p - 1]));
                // Python's lookbehind sees `lt{2}-` / `lt-lt-` ending AT the hyphen.
                let behind = behind && (p + 1 <= n) && true;
                let ahead = p + 2 < n + 0
                    && is_letter(tok[p + 1])
                    && (is_letter(tok[p + 2])
                        || (tok[p + 2] == '-' && p + 3 < n && is_letter(tok[p + 3])));
                if behind && ahead {
                    p += 1;
                    break;
                }
            }
            if p == n {
                break;
            }
            if is_wp(tok[p - 1]) && tok[p] == '-' {
                let mut e = p;
                while e < n && tok[e] == '-' {
                    e += 1;
                }
                if e - p >= 2 && e < n && is_word(tok[e]) {
                    break;
                }
            }
            p += 1;
        }
        out.push(tok[start..p].iter().collect());
        start = p;
    }
    out
}

fn chunks(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut word: Vec<char> = Vec::new();
    let flush = |word: &mut Vec<char>, out: &mut Vec<String>| {
        if !word.is_empty() {
            out.extend(split_word(word));
            word.clear();
        }
    };
    for c in text.chars() {
        if c == ' ' {
            flush(&mut word, &mut out);
            // consecutive spaces form one whitespace chunk
            match out.last_mut() {
                Some(last) if last.chars().all(|x| x == ' ') => last.push(' '),
                _ => out.push(" ".to_string()),
            }
        } else {
            word.push(c);
        }
    }
    flush(&mut word, &mut out);
    out
}

/// `textwrap.wrap(text, width)` / `fill` with the given indents (text is pre-collapsed).
fn wrap(text: &str, width: usize, initial: &str, subsequent: &str) -> Vec<String> {
    let mut rev: Vec<String> = chunks(text);
    rev.reverse();
    let mut lines: Vec<String> = Vec::new();
    while !rev.is_empty() {
        let mut cur: Vec<String> = Vec::new();
        let mut cur_len = 0usize;
        let indent = if lines.is_empty() {
            initial
        } else {
            subsequent
        };
        let w = width.saturating_sub(len(indent));
        if rev.last().is_some_and(|c| c.trim().is_empty()) && !lines.is_empty() {
            rev.pop();
        }
        while let Some(chunk) = rev.last() {
            let l = len(chunk);
            if cur_len + l <= w {
                cur.push(rev.pop().unwrap());
                cur_len += l;
            } else {
                break;
            }
        }
        if rev.last().is_some_and(|c| len(c) > w) {
            // _handle_long_word
            let space_left = if w < 1 { 1 } else { w - cur_len };
            let chunk: Vec<char> = rev.pop().unwrap().chars().collect();
            let mut end = space_left;
            if chunk.len() > space_left {
                let hyphen = chunk[..space_left.min(chunk.len())]
                    .iter()
                    .rposition(|c| *c == '-');
                if let Some(h) = hyphen {
                    if h > 0 && chunk[..h].iter().any(|c| *c != '-') {
                        end = h + 1;
                    }
                }
            }
            let end = end.min(chunk.len());
            cur.push(chunk[..end].iter().collect());
            if end < chunk.len() {
                rev.push(chunk[end..].iter().collect());
            }
        }
        if cur.last().is_some_and(|c| c.trim().is_empty()) {
            cur.pop();
        }
        if !cur.is_empty() {
            lines.push(format!("{indent}{}", cur.concat()));
        }
    }
    lines
}

fn collapse(text: &str) -> String {
    text.split_ascii_whitespace().collect::<Vec<_>>().join(" ")
}

// ---- formatter --------------------------------------------------------------------------

/// One argparse action as the formatter sees it.
struct Act<'a> {
    /// `Some` for a real argument; `None` for the subparsers action.
    arg: Option<&'a Arg>,
    /// `-h/--help`.
    is_help: bool,
    cmd: &'a Cmd,
}

impl Act<'_> {
    fn flags(&self) -> Vec<&str> {
        if self.is_help {
            // prefix_chars="\0" (herdr): argparse builds the help flags from that prefix.
            if self.cmd.raw {
                vec!["\0h", "\0\0help"]
            } else {
                vec!["-h", "--help"]
            }
        } else {
            self.arg.map(|a| a.flags.to_vec()).unwrap_or_default()
        }
    }
    fn positional(&self) -> bool {
        !self.is_help && self.arg.is_none_or(|a| a.positional)
    }
    fn takes_value(&self) -> bool {
        if self.is_help {
            return false;
        }
        match self.arg {
            None => true,
            Some(a) => !matches!(a.kind, Kind::StoreTrue | Kind::StoreFalse | Kind::Version),
        }
    }
    fn help(&self) -> Option<&str> {
        if self.is_help {
            return Some("show this help message and exit");
        }
        match self.arg {
            None => None,
            Some(a) if a.kind == Kind::Version => Some("show program's version number and exit"),
            Some(a) => a.help,
        }
    }
    fn hidden(&self) -> bool {
        self.arg.is_some_and(|a| a.hidden)
    }
}

fn metavar(act: &Act, default: &str) -> String {
    match act.arg {
        None => act.cmd.sub_metavar.map(str::to_string).unwrap_or_else(|| {
            let names: Vec<&str> = act.cmd.subs.iter().map(|s| s.name).collect();
            format!("{{{}}}", names.join(","))
        }),
        Some(a) => {
            if let Some(m) = a.metavar {
                m.to_string()
            } else if !a.choices.is_empty() {
                format!("{{{}}}", a.choices.join(","))
            } else {
                default.to_string()
            }
        }
    }
}

fn format_args(act: &Act, default: &str) -> String {
    let mv = metavar(act, default);
    match act.arg {
        None => format!("{mv} ..."),
        Some(a) => match a.nargs {
            Nargs::One => mv,
            Nargs::Opt => format!("[{mv}]"),
            Nargs::Star => format!("[{mv} ...]"),
            Nargs::Plus => format!("{mv} [{mv} ...]"),
            Nargs::Zero => String::new(),
        },
    }
}

fn default_metavar(act: &Act) -> String {
    let dest = act.arg.map_or("", |a| a.dest);
    if act.positional() {
        dest.to_string()
    } else {
        dest.to_uppercase()
    }
}

fn invocation(act: &Act) -> String {
    if act.positional() {
        return metavar(act, &default_metavar(act));
    }
    let flags = act.flags().join(", ");
    if !act.takes_value() {
        flags
    } else {
        format!("{flags} {}", format_args(act, &default_metavar(act)))
    }
}

fn usage_parts(acts: &[&Act]) -> (Vec<String>, usize) {
    let acts: Vec<&&Act> = acts.iter().filter(|a| !a.hidden()).collect();
    // mutually exclusive groups, by member dest
    let group_of = |act: &Act| -> Option<usize> {
        let dest = act.arg?.dest;
        act.cmd
            .groups
            .iter()
            .position(|g| g.members.contains(&dest))
    };
    let mut taken = vec![false; acts.len()];
    let mut positionals: Vec<(Option<bool>, Vec<usize>)> = Vec::new();
    let mut optionals: Vec<(Option<bool>, Vec<usize>)> = Vec::new();
    for (i, act) in acts.iter().enumerate() {
        if act.positional() && !taken[i] {
            taken[i] = true;
            match group_of(act) {
                Some(g) => {
                    let mut members: Vec<usize> = Vec::new();
                    for (j, other) in acts.iter().enumerate() {
                        if !other.positional() && !taken[j] && group_of(other) == Some(g) {
                            taken[j] = true;
                            members.push(j);
                        }
                    }
                    members.push(i);
                    positionals.push((Some(act.cmd.groups[g].required), members));
                }
                None => positionals.push((None, vec![i])),
            }
        }
    }
    for (i, act) in acts.iter().enumerate() {
        if !act.positional() && !taken[i] {
            taken[i] = true;
            match group_of(act) {
                Some(g) => {
                    let mut members = vec![i];
                    for (j, other) in acts.iter().enumerate() {
                        if !other.positional() && !taken[j] && group_of(other) == Some(g) {
                            taken[j] = true;
                            members.push(j);
                        }
                    }
                    optionals.push((Some(act.cmd.groups[g].required), members));
                }
                None => optionals.push((None, vec![i])),
            }
        }
    }
    let mut parts: Vec<String> = Vec::new();
    let mut pos_start = None;
    let n_opt = optionals.len();
    for (index, (required, group)) in optionals.iter().chain(positionals.iter()).enumerate() {
        let start = parts.len();
        if index == n_opt {
            pos_start = Some(start);
        }
        let in_group = group.len() > 1;
        for &member in group {
            let act = acts[member];
            let part = if act.positional() {
                let mut part = format_args(act, &default_metavar(act));
                if in_group && part.starts_with('[') && part.ends_with(']') {
                    part = part[1..part.len() - 1].to_string();
                }
                part
            } else {
                let first = act.flags()[0].to_string();
                let mut part = if !act.takes_value() {
                    first
                } else {
                    format!("{first} {}", format_args(act, &default_metavar(act)))
                };
                let arg_required = act.arg.is_some_and(|a| a.required);
                if !(arg_required || required.unwrap_or(false) || in_group) {
                    part = format!("[{part}]");
                }
                part
            };
            parts.push(part);
        }
        if in_group {
            let req = required.unwrap_or(false);
            parts[start] = format!("{}{}", if req { '(' } else { '[' }, parts[start]);
            let last = parts.len() - 1;
            for part in parts.iter_mut().take(last).skip(start) {
                part.push_str(" |");
            }
            parts[last].push(if req { ')' } else { ']' });
        }
    }
    let pos_start = pos_start.unwrap_or(parts.len());
    (parts, pos_start)
}

fn get_lines(
    parts: &[String],
    indent: &str,
    prefix: Option<&str>,
    text_width: usize,
) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    let mut line: Vec<&String> = Vec::new();
    let indent_len = len(indent);
    let mut line_len: isize = match prefix {
        Some(p) => len(p) as isize - 1,
        None => indent_len as isize - 1,
    };
    for part in parts {
        let part_len = len(part) as isize;
        if line_len + 1 + part_len > text_width as isize && !line.is_empty() {
            lines.push(format!(
                "{indent}{}",
                line.iter()
                    .map(|s| s.as_str())
                    .collect::<Vec<_>>()
                    .join(" ")
            ));
            line.clear();
            line_len = indent_len as isize - 1;
        }
        line.push(part);
        line_len += part_len + 1;
    }
    if !line.is_empty() {
        lines.push(format!(
            "{indent}{}",
            line.iter()
                .map(|s| s.as_str())
                .collect::<Vec<_>>()
                .join(" ")
        ));
    }
    if prefix.is_some() {
        if let Some(first) = lines.first_mut() {
            *first = first.chars().skip(indent_len).collect();
        }
    }
    lines
}

fn format_usage(prog: &str, acts: &[&Act], width: usize) -> String {
    let prefix = "usage: ";
    let (parts, pos_start) = usage_parts(acts);
    let mut all = vec![prog.to_string()];
    all.extend(parts.iter().cloned());
    let mut usage = all.join(" ");
    let text_width = width;
    if len(prefix) + len(&usage) > text_width {
        let opt_parts = &parts[..pos_start];
        let pos_parts = &parts[pos_start..];
        let prog_len = len(prog);
        let lines: Vec<String>;
        if (len(prefix) + prog_len) as f64 <= 0.75 * text_width as f64 {
            let indent = " ".repeat(len(prefix) + prog_len + 1);
            if !opt_parts.is_empty() {
                let mut first = vec![prog.to_string()];
                first.extend(opt_parts.iter().cloned());
                let mut l = get_lines(&first, &indent, Some(prefix), text_width);
                l.extend(get_lines(pos_parts, &indent, None, text_width));
                lines = l;
            } else if !pos_parts.is_empty() {
                let mut first = vec![prog.to_string()];
                first.extend(pos_parts.iter().cloned());
                lines = get_lines(&first, &indent, Some(prefix), text_width);
            } else {
                lines = vec![prog.to_string()];
            }
        } else {
            let indent = " ".repeat(len(prefix));
            let mut joined: Vec<String> = opt_parts.to_vec();
            joined.extend(pos_parts.iter().cloned());
            let mut l = get_lines(&joined, &indent, None, text_width);
            if l.len() > 1 {
                l = get_lines(opt_parts, &indent, None, text_width);
                l.extend(get_lines(pos_parts, &indent, None, text_width));
            }
            let mut with_prog = vec![prog.to_string()];
            with_prog.extend(l);
            lines = with_prog;
        }
        usage = lines.join("\n");
    }
    let usage = usage.strip_prefix(prog).unwrap_or(&usage).to_string();
    format!("{prefix}{prog}{usage}\n\n")
}

struct Layout {
    width: usize,
    help_position: usize,
}

fn format_action_line(header: &str, help: Option<&str>, indent: usize, l: &Layout) -> String {
    let help_width = l.width.saturating_sub(l.help_position).max(11);
    let action_width = l.help_position as isize - indent as isize - 2;
    let mut out = String::new();
    let indent_first;
    match help {
        None | Some("") => {
            out.push_str(&format!("{}{header}\n", " ".repeat(indent)));
            return out;
        }
        Some(_) if (len(header) as isize) <= action_width => {
            out.push_str(&format!(
                "{}{header}{}  ",
                " ".repeat(indent),
                " ".repeat((action_width as usize).saturating_sub(len(header)))
            ));
            indent_first = 0;
        }
        Some(_) => {
            out.push_str(&format!("{}{header}\n", " ".repeat(indent)));
            indent_first = l.help_position;
        }
    }
    let text = collapse(help.unwrap_or(""));
    let lines = wrap(&text, help_width, "", "");
    if let Some(first) = lines.first() {
        out.push_str(&format!("{}{first}\n", " ".repeat(indent_first)));
        for line in &lines[1..] {
            out.push_str(&format!("{}{line}\n", " ".repeat(l.help_position)));
        }
    }
    out
}

fn subaction_label(sub: &Cmd) -> String {
    if sub.aliases.is_empty() {
        sub.name.to_string()
    } else {
        format!("{} ({})", sub.name, sub.aliases.join(", "))
    }
}

fn format_action(act: &Act, indent: usize, l: &Layout) -> String {
    let mut out = format_action_line(&invocation(act), act.help(), indent, l);
    if act.arg.is_none() && !act.is_help {
        for sub in act.cmd.subs.iter().filter(|s| s.help.is_some()) {
            out.push_str(&format_action_line(
                &subaction_label(sub),
                sub.help,
                indent + INDENT_INCREMENT,
                l,
            ));
        }
    }
    out
}

fn text_block(text: &str, raw: bool, width: usize) -> String {
    if raw {
        return format!("{text}\n\n");
    }
    let collapsed = collapse(text);
    format!("{}\n\n", wrap(&collapsed, width, "", "").join("\n"))
}

/// `parser.format_help()` for the command at `path` (`[]` is the root).
pub fn help(path: &[&str], columns: usize) -> Option<String> {
    let mut cmd: &Cmd = &crate::cli_table::ROOT;
    let mut prog = vec![cmd.name.to_string()];
    for name in path {
        cmd = cmd.subs.iter().find(|s| s.name == *name)?;
        prog.push(cmd.name.to_string());
    }
    let prog = prog.join(" ");
    let width = columns.saturating_sub(2);
    let help_act = Act {
        arg: None,
        is_help: true,
        cmd,
    };
    let mut acts: Vec<Act> = vec![help_act];
    for (i, arg) in cmd.args.iter().enumerate() {
        if cmd.sub_at == Some(i) {
            acts.push(Act {
                arg: None,
                is_help: false,
                cmd,
            });
        }
        acts.push(Act {
            arg: Some(arg),
            is_help: false,
            cmd,
        });
    }
    if cmd.sub_at == Some(cmd.args.len()) {
        acts.push(Act {
            arg: None,
            is_help: false,
            cmd,
        });
    }
    let refs: Vec<&Act> = acts.iter().collect();

    // add_argument: the widest invocation decides where the help column starts.
    let mut max_len = 0usize;
    for act in acts.iter().filter(|a| !a.hidden()) {
        max_len = max_len.max(len(&invocation(act)) + INDENT_INCREMENT);
        if act.arg.is_none() && !act.is_help {
            for sub in cmd.subs.iter().filter(|s| s.help.is_some()) {
                max_len = max_len.max(len(&subaction_label(sub)) + 2 * INDENT_INCREMENT);
            }
        }
    }
    let max_help = MAX_HELP_POSITION.min(width.saturating_sub(20).max(INDENT_INCREMENT * 2));
    let layout = Layout {
        width,
        help_position: (max_len + 2).min(max_help),
    };

    let mut out = format_usage(&prog, &refs, width);
    if let Some(desc) = cmd.about.filter(|d| !d.is_empty()) {
        out.push_str(&text_block(desc, cmd.raw_desc, width));
    }
    for (title, positional) in [("positional arguments", true), ("options", false)] {
        let body: String = acts
            .iter()
            .filter(|a| !a.hidden() && a.positional() == positional)
            .map(|a| format_action(a, INDENT_INCREMENT, &layout))
            .collect();
        if !body.is_empty() {
            out.push_str(&format!("\n{title}:\n{body}\n"));
        }
    }
    if let Some(epilog) = cmd.epilog.filter(|d| !d.is_empty()) {
        // The epilog is not inside a section, so it is not indented.
        out.push_str(&text_block(epilog, cmd.raw_desc, width));
    }
    // format_help: collapse 3+ newlines to 2, then exactly one trailing newline.
    let mut collapsed = String::new();
    let mut run = 0;
    for c in out.chars() {
        if c == '\n' {
            run += 1;
            if run <= 2 {
                collapsed.push(c);
            }
        } else {
            run = 0;
            collapsed.push(c);
        }
    }
    Some(format!("{}\n", collapsed.trim_matches('\n')))
}
